contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function with inputs: amount to send to c.go
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance to send");

        // read owner before call via public getter
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        // read contract balance before
        uint balBefore = address(c).balance;

        // perform the state-changing call on c: send Ether to c.go
        bool didRevert;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            didRevert = true;
        } else {
            didRevert = false;
        }

        // observe after values
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint balAfter = address(c).balance;

        // If the call did not revert, then all Ether that was in C after the call must be zero
        // and the owner must remain unchanged. If it reverted, we make no claim about balances but still
        // require owner unchanged because go does not modify owner even on revert.
        assert(ownerBefore == ownerAfter && (didRevert || balAfter == 0));
    }

    // contract must be able to receive refunds/transfers during calls
    receive() external payable {}
}

